import { useState, useEffect } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  Box,
  Typography,
  TextField,
  Button,
  Card,
  CardContent,
  Modal,
  CircularProgress,
} from "@mui/material";
import { supabase } from "../supabaseClient"; // make sure this file exports the client

const SignUpPage = () => {
  const [name, setName] = useState("");
  const [dob, setDob] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [verifyStatus, setVerifyStatus] = useState("waiting"); // "waiting" | "success" | "failed"

  const navigate = useNavigate();

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError(null);

    if (!name || !dob || !email || !password) {
      setError("All fields are required!");
      return;
    }

    setLoading(true);

    const { error: signUpError } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { name, dob },
        emailRedirectTo: "http://localhost:3000", // or your deployed URL
      },
    });

    setLoading(false);

    if (signUpError) {
      setError(signUpError.message);
    } else {
      setModalOpen(true); // Open modal after signup
    }
  };

  // Automatically check for verification when redirected back with hash
  useEffect(() => {
    const hash = window.location.hash;
    if (hash.includes("access_token")) {
      (async () => {
        const { error } = await supabase.auth.exchangeCodeForSession();
        if (error) {
          setVerifyStatus("failed");
        } else {
          setVerifyStatus("success");
        }
        setModalOpen(true);
      })();
    }
  }, []);

  return (
    <>
      {/* Signup Form */}
      <Box sx={{ width: "100vw", height: "100vh", display: "flex", overflow: "hidden" }}>
        <Box
          sx={{
            width: "50%",
            backgroundColor: "#8E2839",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            color: "white",
            padding: "40px",
            position: "relative",
            "&::before": {
              content: '""',
              position: "absolute",
              top: 0,
              right: "-50px",
              width: "100px",
              height: "100%",
              backgroundColor: "#FFF",
              borderRadius: "50%",
            },
          }}
        >
          <Typography variant="h4" fontWeight="bold" mb={2}>
            Welcome Back!
          </Typography>
          <Typography textAlign="center" mb={4} fontSize="1.125rem">
            To keep connected with us, please login with your personal info
          </Typography>
          <Link to="/signin">
            <Button
              variant="outlined"
              sx={{
                color: "white",
                borderColor: "white",
                padding: "10px 32px",
                borderRadius: "999px",
                fontSize: "1rem",
                transition: "0.3s",
                "&:hover": {
                  backgroundColor: "white",
                  color: "#8E2839",
                },
              }}
            >
              SIGN IN
            </Button>
          </Link>
        </Box>

        <Box
          sx={{
            width: "50%",
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            alignItems: "center",
            backgroundColor: "#FFF",
          }}
        >
          <Card sx={{ width: "90%", maxWidth: 420, padding: 3, boxShadow: 3, borderRadius: 3 }}>
            <CardContent>
              <Typography variant="h4" fontWeight="bold" color="#8E2839" mb={1}>
                Create Account
              </Typography>
              <Typography color="gray" mb={3}>
                Sign up to enjoy the feature of EXAM
              </Typography>

              <form onSubmit={handleSignUp}>
                <TextField
                  fullWidth
                  label="Full Name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  required
                  sx={{ mb: 2 }}
                />
                <TextField
                  fullWidth
                  type="date"
                  label="Date of Birth"
                  value={dob}
                  onChange={(e) => setDob(e.target.value)}
                  InputLabelProps={{ shrink: true }}
                  required
                  sx={{ mb: 2 }}
                />
                <TextField
                  fullWidth
                  type="email"
                  label="Email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  sx={{ mb: 2 }}
                />
                <TextField
                  fullWidth
                  type="password"
                  label="Password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  sx={{ mb: 2 }}
                />
                {error && (
                  <Typography color="red" fontSize="0.875rem" mb={2}>
                    {error}
                  </Typography>
                )}
                <Button
                  type="submit"
                  fullWidth
                  disabled={loading}
                  sx={{
                    backgroundColor: loading ? "#aaa" : "#8E2839",
                    color: "white",
                    padding: "12px",
                    borderRadius: "999px",
                    fontSize: "1.125rem",
                    transition: "0.3s",
                    "&:hover": {
                      backgroundColor: loading ? "#aaa" : "#7A2231",
                    },
                  }}
                >
                  {loading ? "Creating Account..." : "Create Account"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </Box>
      </Box>

      {/* Modal for verification feedback */}
      <Modal open={modalOpen} onClose={() => setModalOpen(false)}>
        <Box
          sx={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            bgcolor: "background.paper",
            boxShadow: 24,
            borderRadius: 2,
            p: 4,
            minWidth: 300,
            textAlign: "center",
          }}
        >
          {verifyStatus === "waiting" && (
            <>
              <CircularProgress />
              <Typography mt={2}>Please check your email to verify your account.</Typography>
            </>
          )}
          {verifyStatus === "success" && (
            <>
              <Typography variant="h6" color="green" mb={2}>
                ✅ Email Verified!
              </Typography>
              <Button variant="contained" onClick={() => navigate("/signin")}>
                Proceed to Sign In
              </Button>
            </>
          )}
          {verifyStatus === "failed" && (
            <>
              <Typography variant="h6" color="error" mb={1}>
                ❌ Verification Failed
              </Typography>
              <Typography mb={2}>Link may be expired or already used.</Typography>
              <Button variant="outlined" onClick={() => setModalOpen(false)}>
                Close
              </Button>
            </>
          )}
        </Box>
      </Modal>
    </>
  );
};

export default SignUpPage;
